CREATE   PROCEDURE dbo.usp_merge_validation_clusters      @payload NVARCHAR(MAX)  AS  BEGIN      SET NOCOUNT ON;      ;WITH src AS (          SELECT *          FROM OPENJSON(@payload, '$.rows')          WITH (              row_id        NVARCHAR(100)  '$.row_id',              block_id      NVARCHAR(100)  '$.block_id',              cluster_id    NVARCHAR(100)  '$.cluster_id',   -- was INT; it's a content hash string              routing       NVARCHAR(30)   '$.routing',              signature_id  NVARCHAR(100)  '$.signature_id',              confidence    FLOAT          '$.confidence',              reasoning     NVARCHAR(MAX)  '$.reasoning'          )      )      MERGE test_77.Validation AS tgt      USING src ON tgt.Customer = src.row_id      WHEN MATCHED THEN UPDATE SET          tgt.[Block ID]      = src.block_id,          tgt.[Cluster ID]    = src.cluster_id,          tgt.[Routing]       = src.routing,          tgt.[Signature ID]  = src.signature_id,          tgt.[Confidence]    = src.confidence,          tgt.[Reasoning]     = src.reasoning;  END